<script setup>
import {ref} from 'vue';import axios from 'axios';import {message} from '../art';
const props=defineProps({question:Object}),open=ref(false),category=ref('unclear'),details=ref(''),busy=ref(false),status=ref('');
async function send(){busy.value=true;status.value='';try{const r=await axios.post('/questions/'+props.question.id+'/report',{category:category.value,details:details.value,version:props.question.version});status.value=r.data.message;open.value=false;details.value=''}catch(e){status.value=message(e)}finally{busy.value=false}}
</script>
<template><div class="report-question"><button @click="open=!open" :aria-expanded="open">Report an issue</button><form v-if="open" @submit.prevent="send"><h4>Report {{question.id}} · version {{question.version}}</h4><label>Issue<select v-model="category"><option value="unclear">Unclear question</option><option value="answer">Disputed answer</option><option value="reference">Outdated reference</option><option value="typo">Typo</option></select></label><label>Tell Head Chef what to review<textarea v-model="details" required minlength="5" maxlength="3000" rows="3"></textarea></label><button class="primary" :disabled="busy">Send report</button></form><p role="status">{{status}}</p></div></template>
